pub fn appendFloats(list: *std.ArrayListUnmanaged(f32), values: []const f32) bool {
    for (values) |v| list.append(std.heap.c_allocator, v) catch return false;
    return true;
}

pub fn appendVertex(list: *std.ArrayListUnmanaged(f32), p: [3]f32, n: [3]f32) bool {
    const row = [_]f32{ p[0], p[1], p[2], n[0], n[1], n[2], 0, 0 };
    return z3d.appendFloats(list, row[0..]);
}

pub fn appendTri(list: *std.ArrayListUnmanaged(f32), a: [3]f32, b: [3]f32, c: [3]f32) bool {
    const n = z3d.normalOf(a, b, c);
    return z3d.appendVertex(list, a, n) and z3d.appendVertex(list, b, n) and z3d.appendVertex(list, c, n);
}

pub fn appendTriWithUvs(
    list: *std.ArrayListUnmanaged(f32),
    a: [3]f32,
    b: [3]f32,
    c: [3]f32,
    uvs: [3][2]f32,
) bool {
    const n = z3d.normalOf(a, b, c);
    const positions = [3][3]f32{ a, b, c };
    for (positions, 0..) |position, corner| {
        const row = [_]f32{
            position[0],    position[1],    position[2],
            n[0],           n[1],           n[2],
            uvs[corner][0], uvs[corner][1],
        };
        if (!z3d.appendFloats(list, &row)) return false;
    }
    return true;
}

/// Re-lower a same-face-count indexed mesh after live mirror mode synchronized quad
/// diagonals. This is not a structural edit: authored face slots, groups, materials,
/// parts, atlas pixels, and the paint program all remain valid. Installing in place
/// avoids the generic topology-replace path, which would clear selection and mark the
/// paint layout stale even though only the two render triangles inside a quad changed.
pub fn installMirrorSynchronizedTriangulation() bool {
    const edit_verts = z3d.g_edit_verts orelse return false;
    const mesh = &(z3d.g_indexed_edit_mesh orelse return false);
    var lowered = mesh.lower() catch return false;
    defer lowered.deinit();
    if (lowered.tri_count * 3 != z3d.g_edit_count or
        edit_verts.len < @as(usize, z3d.g_edit_count) * 8 or
        model_source.count() != z3d.g_edit_count)
    {
        return false;
    }

    const current_groups = z3d.captureFaceGroups() orelse return false;
    defer std.heap.c_allocator.free(current_groups);
    const current_parts = z3d.capturePartOfFaces();
    defer if (current_parts) |parts| std.heap.c_allocator.free(parts);
    const current_materials = z3d.captureFaceMaterials(lowered.tri_count) orelse return false;
    defer std.heap.c_allocator.free(current_materials);
    const parts_match = if (current_parts) |parts|
        std.mem.eql(u32, parts, lowered.parts)
    else blk: {
        for (lowered.parts) |part| if (part != indexed_edit_mesh.NO_PART) break :blk false;
        break :blk true;
    };
    if (!std.mem.eql(u32, current_groups, lowered.groups) or
        !parts_match or
        !std.mem.eql(u32, current_materials, lowered.materials))
    {
        return false;
    }

    var interleaved = std.ArrayListUnmanaged(f32).empty;
    defer interleaved.deinit(std.heap.c_allocator);
    interleaved.ensureTotalCapacity(std.heap.c_allocator, @as(usize, z3d.g_edit_count) * 8) catch return false;
    var triangle: u32 = 0;
    while (triangle < lowered.tri_count) : (triangle += 1) {
        const position_base = @as(usize, triangle) * 9;
        const uv_base = @as(usize, triangle) * 6;
        const p0: [3]f32 = .{ lowered.positions[position_base], lowered.positions[position_base + 1], lowered.positions[position_base + 2] };
        const p1: [3]f32 = .{ lowered.positions[position_base + 3], lowered.positions[position_base + 4], lowered.positions[position_base + 5] };
        const p2: [3]f32 = .{ lowered.positions[position_base + 6], lowered.positions[position_base + 7], lowered.positions[position_base + 8] };
        const uvs = [3][2]f32{
            .{ lowered.uvs[uv_base], lowered.uvs[uv_base + 1] },
            .{ lowered.uvs[uv_base + 2], lowered.uvs[uv_base + 3] },
            .{ lowered.uvs[uv_base + 4], lowered.uvs[uv_base + 5] },
        };
        if (!z3d.appendTriWithUvs(&interleaved, p0, p1, p2, uvs)) return false;
    }
    if (interleaved.items.len != @as(usize, z3d.g_edit_count) * 8) return false;

    const groups_arg: ?[]const u32 = if (model_source.faceGroupOf(0) == model_source.NO_FACE_GROUP)
        null
    else
        current_groups;
    if (!model_paint.setTargetPreservingAtlas(z3d.g_edit_key_hash, interleaved.items, z3d.g_edit_count, groups_arg)) return false;
    mesh.has_explicit_logical_topology = true;
    if (!model_source.replaceGeometryAndLogicalTopologySameTriangleCount(
        interleaved.items,
        z3d.g_edit_count,
        z3d.flattenedLogicalRows(lowered.triangle_vertices),
        @intCast(mesh.vertices.items.len),
    )) return false;
    @memcpy(edit_verts[0..interleaved.items.len], interleaved.items);
    mesh.adoptLoweredMetadata(&lowered, groups_arg, lowered.parts);
    if (!mesh_edit.adoptSameFaceTriangulation()) return false;
    return if (lowered.tri_count > 0) z3d.patchActiveEditMesh(0, lowered.tri_count - 1) else true;
}

pub fn triArea2(a: [3]f32, b: [3]f32, c: [3]f32) f32 {
    const cr = z3d.vcross(z3d.vsub(b, a), z3d.vsub(c, a));
    return z3d.vdot(cr, cr);
}

pub fn appendQuadSplit(list: *std.ArrayListUnmanaged(f32), a: [3]f32, b: [3]f32, c: [3]f32, d: [3]f32) bool {
    const score_ac = @min(z3d.triArea2(a, b, c), z3d.triArea2(a, c, d));
    const score_bd = @min(z3d.triArea2(a, b, d), z3d.triArea2(b, c, d));
    if (score_bd > score_ac) {
        return z3d.appendTri(list, a, b, d) and z3d.appendTri(list, b, c, d);
    }
    return z3d.appendTri(list, a, b, c) and z3d.appendTri(list, a, c, d);
}

pub fn appendTriFacing(list: *std.ArrayListUnmanaged(f32), a: [3]f32, b: [3]f32, c: [3]f32, reference: [3]f32) bool {
    return if (z3d.vdot(z3d.normalOf(a, b, c), reference) >= 0)
        z3d.appendTri(list, a, b, c)
    else
        z3d.appendTri(list, a, c, b);
}

pub fn appendQuadSplitFacing(
    list: *std.ArrayListUnmanaged(f32),
    a: [3]f32,
    b: [3]f32,
    c: [3]f32,
    d: [3]f32,
    reference: [3]f32,
) bool {
    const area_normal = z3d.vadd(z3d.vcross(z3d.vsub(b, a), z3d.vsub(c, a)), z3d.vcross(z3d.vsub(c, a), z3d.vsub(d, a)));
    return if (z3d.vdot(area_normal, reference) >= 0)
        z3d.appendQuadSplit(list, a, b, c, d)
    else
        z3d.appendQuadSplit(list, a, d, c, b);
}

/// A face's TRUE colour: the saved pre-tint base when the face is selection-tinted,
/// else the live atlas centroid texel. Every colour snapshot/carry reads through this
/// so the selection orange never bakes into carried or journaled colours.
///
/// While the paint layout is STALE the atlas is FROZEN against an older
/// tessellation: reading its texels through the current face table can land in
/// unowned padding and launder (0,0,0) into every colour capture — the spreading
/// black bars (req_3468: each op inherited the zeros, so "it gets worse with
/// every edit"). The durable source row is the only trustworthy colour then.
pub fn trueFaceColor(f: u32) [4]u8 {
    if (mesh_edit.savedFaceBaseColor(f)) |c| return c;
    if (z3d.g_paint_layout_stale) {
        if (model_source.colorOf(f)) |c| return c;
        return model_paint.DEFAULT_FACE;
    }
    return model_paint.faceColor(f) orelse model_paint.DEFAULT_FACE;
}

/// One colour per face of the LIVE MESH — sized by the mesh, never by the paint layout
/// (req_4114). Topology editing must never require a UV/paint layout to exist, to be
/// current, or to agree with the mesh: nobody unwraps a model they are still cutting.
/// `trueFaceColor` already falls back to DEFAULT_FACE for any face the layout does not
/// cover, so a stale, degenerate, or absent atlas yields default colours here instead of
/// a null that refused the whole operation. Sizing by `model_paint.faceCount()` also
/// silently no-op'd every consumer that (correctly) asserts mesh size —
/// `partitionGlassFaces` and `restoreFaceColorMetadata` among them.
pub fn collectCurrentFaceColors() ?[]u8 {
    const fc = z3d.g_edit_count / 3;
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, fc) * 4) catch return null;
    var f: u32 = 0;
    while (f < fc) : (f += 1) {
        const c = z3d.trueFaceColor(f);
        colors[f * 4 + 0] = c[0];
        colors[f * 4 + 1] = c[1];
        colors[f * 4 + 2] = c[2];
        colors[f * 4 + 3] = c[3];
    }
    return colors;
}

/// Restore durable per-face colour metadata after a hide/show target rebuild without
/// flattening the detailed paint raster. RGB stays source-side; glass alpha returns to
/// the independent face-material table used to route the auxiliary glass atlas.
pub fn restoreFaceColorMetadata(colors: []const u8) void {
    const face_count = z3d.g_edit_count / 3;
    if (colors.len != @as(usize, face_count) * 4) return;
    if (model_source.colors()) |destination| {
        if (destination.len >= colors.len) @memcpy(destination[0..colors.len], colors);
    }
    var face: u32 = 0;
    while (face < face_count) : (face += 1) model_paint.paintFaceAlpha(face, colors[@as(usize, face) * 4 + 3]);
}

pub fn applyCarriedFaceColors(old_colors: ?[]const u8, new_fc: u32) void {
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, new_fc) * 4) catch return;
    defer std.heap.c_allocator.free(colors);
    var f: u32 = 0;
    while (f < new_fc) : (f += 1) {
        colors[f * 4 + 0] = model_paint.DEFAULT_FACE[0];
        colors[f * 4 + 1] = model_paint.DEFAULT_FACE[1];
        colors[f * 4 + 2] = model_paint.DEFAULT_FACE[2];
        colors[f * 4 + 3] = model_paint.DEFAULT_FACE[3];
    }
    if (old_colors) |old| {
        const carry_faces: u32 = @intCast(@min(old.len / 4, @as(usize, new_fc)));
        if (carry_faces > 0) @memcpy(colors[0 .. @as(usize, carry_faces) * 4], old[0 .. @as(usize, carry_faces) * 4]);
    }
    model_paint.applyColors(colors);
    if (model_source.colors()) |src_colors| {
        const n = @min(src_colors.len, colors.len);
        if (n > 0) @memcpy(src_colors[0..n], colors[0..n]);
    }
}

/// Apply an already-parented face-colour table after a topology rebuild. The caller
/// derives these rows through CutResult.src_face; unlike applyCarriedFaceColors this is
/// independent of the previous resident preview's face order (req_2906).
pub fn applyExactFaceColors(colors: []const u8, face_count: u32) bool {
    const need = @as(usize, face_count) * 4;
    if (colors.len != need) return false;
    model_paint.applyColors(colors);
    if (model_source.colors()) |dst| {
        if (dst.len < need) return false;
        @memcpy(dst[0..need], colors);
    }
    return true;
}

/// Update the source-side representative colour table without flooding the paint
/// atlas. Indexed topology installs keep the raster and UVs exactly; applyColors
/// would flatten every detailed face back to this one centroid colour.
pub fn applyExactSourceFaceColors(colors: []const u8, face_count: u32) bool {
    const need = @as(usize, face_count) * 4;
    if (colors.len != need) return false;
    const destination = model_source.colors() orelse return false;
    if (destination.len < need) return false;
    @memcpy(destination[0..need], colors);
    return true;
}

pub const LogicalTopologyReplacement = union(enum) {
    /// The resident document has no explicit logical topology and this operation
    /// does not mint one. Illegal when a current-v5 table is resident: silently
    /// crossing that boundary was the req_4194 data-loss bug.
    absent,
    /// Corner order and logical connectivity are unchanged. Positions, normals,
    /// and UVs may change, but every duplicate carrying one id must still validate.
    preserve_same_order,
    /// Structural mutation supplied the exact post-operation corner provenance.
    exact: struct {
        rows: []const u32,
        vertex_count: u32,
    },
    /// Deleting the final triangle intentionally leaves no logical rows.
    empty,
    /// A verified journal snapshot recorded a document that HAD no logical
    /// topology. Restoring it must clear a resident table (the first structural
    /// op on such a document mints one — undoing that op un-mints it). Journal
    /// restore only; live operations stay behind the `.absent` guard.
    restore_absent,
};

pub fn logicalReplacementExactOrAbsent(
    rows: ?[]const u32,
    count: u32,
    logical_vertex_count: u32,
) z3d.LogicalTopologyReplacement {
    if (count == 0) return .empty;
    if (rows) |exact_rows| return .{ .exact = .{
        .rows = exact_rows,
        .vertex_count = logical_vertex_count,
    } };
    return .absent;
}

/// Journal restores are the one crossing allowed to CLEAR a resident logical
/// table: undoing the first structural op on a document that had no table must
/// un-mint the rows that op created (first-action undo, req_4220).
pub fn logicalReplacementForJournalRestore(
    rows: ?[]const u32,
    count: u32,
    logical_vertex_count: u32,
) z3d.LogicalTopologyReplacement {
    if (count == 0) return .empty;
    if (rows) |exact_rows| return .{ .exact = .{
        .rows = exact_rows,
        .vertex_count = logical_vertex_count,
    } };
    return .restore_absent;
}

/// Parallel provenance stream for soup-building structural operations. Existing
/// corners are copied by source-corner address; new corners are minted explicitly
/// by the operation's own topology recipe. It never discovers resident identity
/// from positions.
pub const LogicalRowsBuilder = struct {
    rows: std.ArrayListUnmanaged(u32) = .empty,
    source_rows: ?[]const u32,
    source_vertex_count: u32,
    next_id: u32,

    pub fn init() ?z3d.LogicalRowsBuilder {
        const source_rows = model_source.renderCornerLogicalIds();
        if (source_rows) |rows| {
            if (rows.len != z3d.g_edit_count or model_source.logicalVertexCount() == 0) return null;
        } else if (model_source.logicalVertexCount() != 0) return null;
        return .{
            .source_rows = source_rows,
            .source_vertex_count = model_source.logicalVertexCount(),
            .next_id = model_source.logicalVertexCount(),
        };
    }

    pub fn deinit(builder: *z3d.LogicalRowsBuilder) void {
        builder.rows.deinit(std.heap.c_allocator);
        builder.* = undefined;
    }

    pub fn enabled(builder: *const z3d.LogicalRowsBuilder) bool {
        return builder.source_rows != null;
    }

    pub fn appendSourceFace(builder: *z3d.LogicalRowsBuilder, face: u32) bool {
        const source = builder.source_rows orelse return true;
        const base = @as(usize, face) * 3;
        if (base + 3 > source.len) return false;
        builder.rows.appendSlice(std.heap.c_allocator, source[base .. base + 3]) catch return false;
        return true;
    }

    pub fn appendAllSource(builder: *z3d.LogicalRowsBuilder) bool {
        const source = builder.source_rows orelse return true;
        builder.rows.appendSlice(std.heap.c_allocator, source) catch return false;
        return true;
    }

    pub fn sourceCorner(builder: *const z3d.LogicalRowsBuilder, face: u32, corner: usize) ?u32 {
        const source = builder.source_rows orelse return 0;
        const at = @as(usize, face) * 3 + corner;
        return if (at < source.len) source[at] else null;
    }

    pub fn appendTriangle(builder: *z3d.LogicalRowsBuilder, ids: [3]u32) bool {
        if (!builder.enabled()) return true;
        builder.rows.appendSlice(std.heap.c_allocator, &ids) catch return false;
        return true;
    }

    pub fn mint(builder: *z3d.LogicalRowsBuilder) ?u32 {
        if (!builder.enabled()) return 0;
        if (builder.next_id == std.math.maxInt(u32)) return null;
        const id = builder.next_id;
        builder.next_id += 1;
        return id;
    }

    pub fn replacement(builder: *const z3d.LogicalRowsBuilder, count: u32) ?z3d.LogicalTopologyReplacement {
        if (count == 0) return .empty;
        if (!builder.enabled()) return .absent;
        if (builder.rows.items.len != count or builder.next_id == 0) return null;
        return .{ .exact = .{
            .rows = builder.rows.items,
            .vertex_count = builder.next_id,
        } };
    }
};

pub const LogicalCloneKey = struct { namespace: u64, source: u32 };
pub const LogicalCloneMap = struct {
    ids: std.AutoHashMapUnmanaged(z3d.LogicalCloneKey, u32) = .empty,

    pub fn deinit(map: *z3d.LogicalCloneMap) void {
        map.ids.deinit(std.heap.c_allocator);
    }

    pub fn getOrMint(map: *z3d.LogicalCloneMap, builder: *z3d.LogicalRowsBuilder, namespace: u64, source: u32) ?u32 {
        if (!builder.enabled()) return 0;
        const entry = map.ids.getOrPut(std.heap.c_allocator, .{ .namespace = namespace, .source = source }) catch return null;
        if (!entry.found_existing) entry.value_ptr.* = builder.mint() orelse return null;
        return entry.value_ptr.*;
    }
};

pub fn appendTriLogical(
    verts: *std.ArrayListUnmanaged(f32),
    logical: *z3d.LogicalRowsBuilder,
    a: [3]f32,
    b: [3]f32,
    c: [3]f32,
    ids: [3]u32,
) bool {
    return z3d.appendTri(verts, a, b, c) and logical.appendTriangle(ids);
}

pub fn appendTriFacingLogical(
    verts: *std.ArrayListUnmanaged(f32),
    logical: *z3d.LogicalRowsBuilder,
    a: [3]f32,
    b: [3]f32,
    c: [3]f32,
    ids: [3]u32,
    reference: [3]f32,
) bool {
    return if (z3d.vdot(z3d.normalOf(a, b, c), reference) >= 0)
        z3d.appendTriLogical(verts, logical, a, b, c, ids)
    else
        z3d.appendTriLogical(verts, logical, a, c, b, .{ ids[0], ids[2], ids[1] });
}

pub fn appendQuadSplitLogical(
    verts: *std.ArrayListUnmanaged(f32),
    logical: *z3d.LogicalRowsBuilder,
    a: [3]f32,
    b: [3]f32,
    c: [3]f32,
    d: [3]f32,
    ids: [4]u32,
) bool {
    const score_ac = @min(z3d.triArea2(a, b, c), z3d.triArea2(a, c, d));
    const score_bd = @min(z3d.triArea2(a, b, d), z3d.triArea2(b, c, d));
    if (score_bd > score_ac) {
        return z3d.appendTriLogical(verts, logical, a, b, d, .{ ids[0], ids[1], ids[3] }) and
            z3d.appendTriLogical(verts, logical, b, c, d, .{ ids[1], ids[2], ids[3] });
    }
    return z3d.appendTriLogical(verts, logical, a, b, c, .{ ids[0], ids[1], ids[2] }) and
        z3d.appendTriLogical(verts, logical, a, c, d, .{ ids[0], ids[2], ids[3] });
}

pub fn appendQuadSplitFacingLogical(
    verts: *std.ArrayListUnmanaged(f32),
    logical: *z3d.LogicalRowsBuilder,
    a: [3]f32,
    b: [3]f32,
    c: [3]f32,
    d: [3]f32,
    ids: [4]u32,
    reference: [3]f32,
) bool {
    const area_normal = z3d.vadd(z3d.vcross(z3d.vsub(b, a), z3d.vsub(c, a)), z3d.vcross(z3d.vsub(c, a), z3d.vsub(d, a)));
    return if (z3d.vdot(area_normal, reference) >= 0)
        z3d.appendQuadSplitLogical(verts, logical, a, b, c, d, ids)
    else
        z3d.appendQuadSplitLogical(verts, logical, a, d, c, b, .{ ids[0], ids[3], ids[2], ids[1] });
}

/// Resolve one legacy live-edit vertex back to an authoritative v5 id only when
/// every resident corner welded into that edit handle agrees on the same stable
/// id. Coincident but intentionally split v5 vertices therefore refuse instead of
/// being guessed together.
/// Why the last `stableLogicalIdForEditVertex` lookup came back null. Four unrelated
/// conditions share that one null, and a caller refusing on it can otherwise only say
/// "no logical row" — which names none of them (req_4205, the `topoRefuseIndexedError`
/// pattern). Only the lookup itself can tell them apart, so it records which.
pub const LogicalIdFailure = union(enum) {
    none,
    no_table,
    stale_table: struct { rows: usize, corners: u32 },
    /// One welded edit vertex whose face corners carry DIFFERENT stable rows: two
    /// coincident logical vertices that were never merged. Common in imports.
    ambiguous: struct { vertex: u32, first: u32, second: u32 },
    unused: u32,
};

pub fn stableLogicalIdForEditVertex(edit_vertex: u32) ?u32 {
    z3d.g_last_logical_id_failure = .none; // a stale cause must never explain a fresh null
    const rows = model_source.renderCornerLogicalIds() orelse {
        z3d.g_last_logical_id_failure = .no_table;
        return null;
    };
    if (!mesh_edit.ensureTopologyPub() or rows.len != z3d.g_edit_count) {
        z3d.g_last_logical_id_failure = .{ .stale_table = .{ .rows = rows.len, .corners = z3d.g_edit_count } };
        return null;
    }
    var found: ?u32 = null;
    var face: u32 = 0;
    while (face < z3d.g_edit_count / 3) : (face += 1) {
        var corner: usize = 0;
        while (corner < 3) : (corner += 1) {
            if (mesh_edit.cornerVertPub(face, @intCast(corner)) != edit_vertex) continue;
            const id = rows[@as(usize, face) * 3 + corner];
            if (found) |prior| {
                if (prior != id) {
                    z3d.g_last_logical_id_failure = .{ .ambiguous = .{ .vertex = edit_vertex, .first = prior, .second = id } };
                    return null;
                }
            } else found = id;
        }
    }
    if (found == null) z3d.g_last_logical_id_failure = .{ .unused = edit_vertex };
    return found;
}

pub fn logicalIdForEditVertex(builder: *const z3d.LogicalRowsBuilder, edit_vertex: u32) ?u32 {
    return if (builder.enabled()) z3d.stableLogicalIdForEditVertex(edit_vertex) else 0;
}

/// The logical row a NEW fill corner should claim (req_4206). Where two surfaces meet at
/// one welded point, that point carries one row per surface, and the strict lookup above
/// refuses the ambiguity. That is right for a lookup and useless for a fill, because the
/// fill's answer is not arbitrary: the face is being built FROM a selected edge, so its
/// corner must claim the same logical vertex the surface beside THAT edge already uses —
/// pick the other one and the new face comes apart from its neighbour the first time
/// anything moves. Refusing here left an ordinary bridge between two touching surfaces
/// impossible to build, with no explanation, which is how this cost an evening.
///
/// Falls through to the strict refusal when no selected edge's own face covers the
/// corner, because then there genuinely is no continuity to preserve.
pub fn fillCornerLogicalId(builder: *const z3d.LogicalRowsBuilder, edit_vertex: u32, edges: []const mesh_edit.Edge) ?u32 {
    if (!builder.enabled()) return 0;
    if (z3d.stableLogicalIdForEditVertex(edit_vertex)) |id| return id;
    switch (z3d.g_last_logical_id_failure) {
        .ambiguous => {},
        else => return null,
    }
    const rows = model_source.renderCornerLogicalIds() orelse return null;
    if (rows.len != z3d.g_edit_count) return null;
    for (edges) |edge| {
        const partner = if (edge[0] == edit_vertex)
            edge[1]
        else if (edge[1] == edit_vertex)
            edge[0]
        else
            continue;
        var face: u32 = 0;
        while (face < z3d.g_edit_count / 3) : (face += 1) {
            var corner_at: ?usize = null;
            var holds_partner = false;
            var corner: usize = 0;
            while (corner < 3) : (corner += 1) {
                const vertex = mesh_edit.cornerVertPub(face, @intCast(corner));
                if (vertex == edit_vertex) corner_at = corner;
                if (vertex == partner) holds_partner = true;
            }
            if (!holds_partner) continue;
            if (corner_at) |shared| return rows[@as(usize, face) * 3 + shared];
        }
    }
    // No selected edge's own face covers this corner, so there is no continuity to
    // prefer — but there is still nothing to refuse over. USER RULING (req_4207):
    // "there is 0 reason it should be blocking." Every row at this point denotes THIS
    // point; which id a new corner inherits is bookkeeping, and bookkeeping does not get
    // to veto a modelling operation. Take the first one deterministically.
    var any: u32 = 0;
    while (any < z3d.g_edit_count / 3) : (any += 1) {
        var corner: u32 = 0;
        while (corner < 3) : (corner += 1) {
            if (mesh_edit.cornerVertPub(any, corner) != edit_vertex) continue;
            return rows[@as(usize, any) * 3 + corner];
        }
    }
    return null;
}

pub fn editVertexForStableLogicalId(stable_id: u32) ?u32 {
    const rows = model_source.renderCornerLogicalIds() orelse return null;
    if (!mesh_edit.ensureTopologyPub() or rows.len != z3d.g_edit_count) return null;
    var found: ?u32 = null;
    var face: u32 = 0;
    while (face < z3d.g_edit_count / 3) : (face += 1) {
        var corner: usize = 0;
        while (corner < 3) : (corner += 1) {
            if (rows[@as(usize, face) * 3 + corner] != stable_id) continue;
            const edit_vertex = mesh_edit.cornerVertPub(face, @intCast(corner));
            if (found) |prior| {
                if (prior != edit_vertex) return null;
            } else found = edit_vertex;
        }
    }
    return found;
}

pub const EdgeLogicalPromotion = enum {
    none,
    /// An exact v5 indexed cache restored the visible resident table that an older
    /// replacement path had dropped. Hidden blocks, if any, were untouched.
    restored_exact_visible,
    /// A genuinely anonymous v1-v4 prop gained one full-model stable namespace.
    minted_legacy_full,
};

pub fn rollbackEdgeLogicalPromotion(promotion: z3d.EdgeLogicalPromotion) void {
    switch (promotion) {
        .none => {},
        .restored_exact_visible => model_source.clearLogicalTopology(),
        .minted_legacy_full => {
            model_source.clearLogicalTopology();
            for (z3d.g_hidden_groups.items) |*hidden| {
                if (hidden.logical_ids) |rows| std.heap.c_allocator.free(rows);
                hidden.logical_ids = null;
                hidden.logical_vertex_count = 0;
            }
        },
    }
}

/// Give the first named edge on an anonymous prop a full resident logical namespace
/// before its path is recorded. Visible faces come first, so their ids are exactly the
/// live legacy edit ids; hidden blocks append into the same namespace. Later opaque /
/// glass sorting moves these rows with their corners instead of renumbering the path.
pub fn mintLegacyLogicalTopologyForEdgeAuthoring() bool {
    if (model_source.renderCornerLogicalIds() != null or model_source.logicalVertexCount() != 0) return false;
    const source = model_source.verts() orelse return false;
    const source_count = model_source.count();
    if (source_count == 0 or source_count % 3 != 0 or z3d.g_edit_count != source_count or
        source.len != @as(usize, source_count) * 8)
    {
        return false;
    }
    for (z3d.g_hidden_groups.items) |hidden| {
        if (hidden.logical_ids != null or hidden.logical_vertex_count != 0 or
            hidden.source_verts.len == 0 or hidden.source_verts.len % 24 != 0)
        {
            return false;
        }
    }

    var total_floats = source.len;
    for (z3d.g_hidden_groups.items) |hidden| {
        total_floats = std.math.add(usize, total_floats, hidden.source_verts.len) catch return false;
    }
    const all_verts = std.heap.c_allocator.alloc(f32, total_floats) catch return false;
    defer std.heap.c_allocator.free(all_verts);
    const all_parts = std.heap.c_allocator.alloc(u32, total_floats / 24) catch return false;
    defer std.heap.c_allocator.free(all_parts);

    var float_at: usize = 0;
    var face_at: usize = 0;
    @memcpy(all_verts[0..source.len], source);
    float_at += source.len;
    const visible_groups = model_source.faceGroups();
    for (0..source_count / 3) |face| {
        const group = if (visible_groups) |groups|
            if (face < groups.len) groups[face] else model_source.NO_FACE_GROUP
        else
            model_source.NO_FACE_GROUP;
        all_parts[face_at] = model_source.partIndexOf(group);
        face_at += 1;
    }
    for (z3d.g_hidden_groups.items) |hidden| {
        @memcpy(all_verts[float_at .. float_at + hidden.source_verts.len], hidden.source_verts);
        float_at += hidden.source_verts.len;
        const hidden_faces = hidden.source_verts.len / 24;
        if (hidden.groups.len != hidden_faces) return false;
        for (hidden.groups) |group| {
            all_parts[face_at] = model_source.partIndexOf(group);
            face_at += 1;
        }
    }
    if (float_at != all_verts.len or face_at != all_parts.len) return false;

    var topology = mesh_edit.legacyLogicalTopologyAlloc(
        std.heap.c_allocator,
        all_verts,
        all_parts,
    ) catch return false;
    defer topology.deinit();
    const logical_vertex_count: u32 = @intCast(topology.vertex_positions.len / 3);
    if (logical_vertex_count == 0 or topology.corner_vertices.len != total_floats / 8) return false;

    const hidden_rows = std.heap.c_allocator.alloc([]u32, z3d.g_hidden_groups.items.len) catch return false;
    defer std.heap.c_allocator.free(hidden_rows);
    var initialized: usize = 0;
    var installed = false;
    defer if (!installed) for (hidden_rows[0..initialized]) |rows| std.heap.c_allocator.free(rows);
    var corner_at: usize = source_count;
    for (z3d.g_hidden_groups.items, 0..) |hidden, index| {
        const corner_count = hidden.source_verts.len / 8;
        hidden_rows[index] = std.heap.c_allocator.dupe(
            u32,
            topology.corner_vertices[corner_at .. corner_at + corner_count],
        ) catch return false;
        initialized += 1;
        corner_at += corner_count;
    }
    if (corner_at != topology.corner_vertices.len or
        !model_source.setLogicalTopology(topology.corner_vertices[0..source_count], logical_vertex_count))
    {
        return false;
    }
    for (z3d.g_hidden_groups.items, 0..) |*hidden, index| {
        hidden.logical_ids = hidden_rows[index];
        hidden.logical_vertex_count = logical_vertex_count;
    }
    installed = true;
    z3d.clearIndexedEditMesh();
    return true;
}

/// Recover an exact existing v5 namespace when one survives in the indexed cache;
/// otherwise mint one only for a genuinely anonymous legacy prop. Falling back from
/// an explicit-but-stale cache to a position weld would silently replace identity.
pub fn prepareLogicalTopologyForEdgeAuthoring() ?z3d.EdgeLogicalPromotion {
    if (model_source.renderCornerLogicalIds() != null and model_source.logicalVertexCount() > 0) return .none;
    if (z3d.g_indexed_edit_mesh) |*indexed| {
        if (indexed.has_explicit_logical_topology) {
            return if (z3d.promoteLogicalTopologyFromExactIndexedCacheForSave())
                .restored_exact_visible
            else
                null;
        }
    }
    return if (z3d.mintLegacyLogicalTopologyForEdgeAuthoring()) .minted_legacy_full else null;
}

/// Validate the candidate table against the exact full save ordering, including
/// hidden blocks and opaque/glass partitioning. This runs before the semantic row is
/// committed, so the authoring door can never report success for a path Save rejects.
pub fn edgeSemanticTableResolvesInCurrentDocument(allocator: std.mem.Allocator, table_json: []const u8) bool {
    var snapshot = z3d.composeDocumentSnapshot(allocator, false) orelse return false;
    defer snapshot.deinit(allocator);
    const logical_rows = snapshot.render_corner_logical_ids orelse return false;
    const dense_to_stable = snapshot.dense_to_stable_logical_ids orelse return false;
    const remapped = model_source.semanticTableForLogicalSnapshotAlloc(
        allocator,
        table_json,
        dense_to_stable,
    ) catch return false;
    defer allocator.free(remapped);
    return model_source.semanticEdgePathsResolveInTopology(
        allocator,
        remapped,
        logical_rows,
        snapshot.logical_vertex_count,
        snapshot.groups,
    ) catch false;
}

pub fn mirroredLogicalId(
    builder: *z3d.LogicalRowsBuilder,
    fresh_twins: *z3d.LogicalCloneMap,
    source_id: u32,
    subset: u8,
) ?u32 {
    if (!builder.enabled()) return 0;
    if (source_id < builder.source_vertex_count) {
        const edit_vertex = z3d.editVertexForStableLogicalId(source_id) orelse return null;
        const twin = mesh_edit.mirrorImageOfVertPub(edit_vertex, subset) orelse return null;
        return z3d.stableLogicalIdForEditVertex(twin);
    }
    return fresh_twins.getOrMint(builder, @as(u64, subset) + 1, source_id);
}

/// Mint topology for a genuinely new, independent soup (Add Part). Position
/// matching is confined to that import boundary; no resident stable id is ever
/// reconstructed or compared by position. The resulting local ids are offset into
/// the live document's stable namespace.
pub fn appendFreshIndependentSoupLogical(
    builder: *z3d.LogicalRowsBuilder,
    verts: []const f32,
    count: u32,
    groups: ?[]const u32,
) bool {
    if (!builder.enabled()) return true;
    if (count == 0 or count % 3 != 0) return false;
    const face_count = count / 3;
    const parts = std.heap.c_allocator.alloc(u32, face_count) catch return false;
    defer std.heap.c_allocator.free(parts);
    @memset(parts, 0);
    var imported = indexed_edit_mesh.Mesh.fromSoup(
        std.heap.c_allocator,
        verts,
        face_count,
        groups,
        parts,
    ) catch return false;
    defer imported.deinit();
    if (imported.render_triangles.items.len != face_count) return false;
    const base = builder.next_id;
    const fresh_count: u32 = @intCast(imported.vertices.items.len);
    if (fresh_count == 0 or base > std.math.maxInt(u32) - fresh_count) return false;
    for (z3d.flattenedLogicalRows(imported.render_triangles.items)) |local_id| {
        builder.rows.append(std.heap.c_allocator, base + local_id) catch return false;
    }
    builder.next_id += fresh_count;
    return true;
}

pub fn logicalReplacementPreflight(new_verts: []const f32, count: u32, replacement: z3d.LogicalTopologyReplacement) bool {
    const need = @as(usize, count) * 8;
    if (new_verts.len < need) return false;
    return switch (replacement) {
        .absent => model_source.renderCornerLogicalIds() == null,
        // The snapshot was validated by journalMeshPreflight; clearing a resident
        // table is the exact restore, not the req_4194 silent drop.
        .restore_absent => count > 0,
        .empty => count == 0,
        .preserve_same_order => if (model_source.renderCornerLogicalIds()) |rows|
            rows.len == count and count > 0 and meshdoc_format.logicalRowsValid(
                std.heap.c_allocator,
                new_verts[0..need],
                rows,
                model_source.logicalVertexCount(),
                false,
            )
        else
            false,
        .exact => |exact| exact.rows.len == count and count > 0 and meshdoc_format.logicalRowsValid(
            std.heap.c_allocator,
            new_verts[0..need],
            exact.rows,
            exact.vertex_count,
            false,
        ),
    };
}

pub fn replaceSourceGeometryWithLogical(
    key: []const u8,
    new_verts: []const f32,
    count: u32,
    replacement: z3d.LogicalTopologyReplacement,
) bool {
    const need = @as(usize, count) * 8;
    return switch (replacement) {
        .absent, .restore_absent, .empty => blk: {
            model_source.retain(key, new_verts[0..need], count);
            break :blk model_source.count() == count and model_source.renderCornerLogicalIds() == null;
        },
        .preserve_same_order => model_source.retainWithLogicalTopology(
            key,
            new_verts[0..need],
            count,
            model_source.renderCornerLogicalIds() orelse return false,
            model_source.logicalVertexCount(),
        ),
        .exact => |exact| model_source.retainWithLogicalTopology(
            key,
            new_verts[0..need],
            count,
            exact.rows,
            exact.vertex_count,
        ),
    };
}

pub fn replaceActiveEditMesh(new_verts: []f32, count: u32, logical: z3d.LogicalTopologyReplacement) bool {
    if (!z3d.residentMutationAllowed(.geometry_journal)) return false;
    const need = @as(usize, count) * 8;
    // count == 0 is a LEGITIMATE state (req_2806: deleting the last part empties the
    // model — the old refuse-to-empty guard was never asked for): setPaintTarget
    // clears the paint target below 3 verts, the empty soup stashes under a fresh
    // key, and the viewer draws nothing.
    if (count != 0 and (count < 3 or new_verts.len < need)) return false;
    if (!z3d.logicalReplacementPreflight(new_verts, count, logical)) return false;
    const old_colors = z3d.collectCurrentFaceColors();
    defer if (old_colors) |c| std.heap.c_allocator.free(c);
    const old_materials: ?[]u32 = if (model_source.faceMaterials()) |rows|
        (std.heap.c_allocator.dupe(u32, rows) catch null)
    else
        null;
    defer if (old_materials) |rows| std.heap.c_allocator.free(rows);
    const old_semantic_regions: ?[]u32 = if (model_source.faceSemanticRegions()) |rows|
        (std.heap.c_allocator.dupe(u32, rows) catch null)
    else
        null;
    defer if (old_semantic_regions) |rows| std.heap.c_allocator.free(rows);
    const old_semantic_instances: ?[]u32 = if (model_source.faceSemanticInstances()) |rows|
        (std.heap.c_allocator.dupe(u32, rows) catch null)
    else
        null;
    defer if (old_semantic_instances) |rows| std.heap.c_allocator.free(rows);
    const old_semantic_table: ?[]u8 = if (model_source.semanticTableJson()) |json|
        (std.heap.c_allocator.dupe(u8, json) catch null)
    else
        null;
    defer if (old_semantic_table) |json| std.heap.c_allocator.free(json);
    // Part ranges are pure authored-group-id spans — they survive every EDIT replace
    // (retain() clears them, which is right for a fresh LOAD but was silently destroying
    // the outliner's part identity on every topology op; req_2644). Ops that change the
    // spans (append/detach/merge/renormalize) overwrite them right after.
    const old_ranges: ?[]u32 = if (model_source.partRanges()) |pr| (std.heap.c_allocator.dupe(u32, pr) catch null) else null;
    defer if (old_ranges) |r| std.heap.c_allocator.free(r);

    const key = z3d.g_edit_key orelse return false;

    // setPaintTarget rewrites UVs for the per-face paint atlas; retain/stash the same
    // mutated vertices so quality changes and first draw see the new topology.
    // An EDIT replace resets the stroke program (strokes can't survive a topology
    // change; the atlas texel carry preserves the pixels) — but the user's LAYER
    // table is organizational setup, not geometry: stash it so the reset re-adopts
    // it instead of nuking the layer list on every eye toggle / topo op (req_2672).
    paint_program.snapshotLayersForCarry();
    if (!z3d.setPaintTargetForGeneration(new_verts, count)) return false;
    if (!z3d.replaceSourceGeometryWithLogical(key, new_verts[0..need], count, logical)) return false;
    // A structural edit at reduced quality commits that displayed topology as the
    // authoritative source immediately; future saves no longer need projection mode.
    z3d.g_save_displayed_projection = false;
    if (old_ranges) |r| model_source.setPartRanges(r);
    // Position/winding/group-only replacements preserve triangle order. Topology
    // replacements with a different face count install their explicit provenance.
    if (old_materials) |rows| if (rows.len == count / 3) model_source.setFaceMaterials(rows);
    if (old_semantic_regions) |regions| if (old_semantic_instances) |instances| {
        if (regions.len == count / 3 and instances.len == count / 3) {
            if (old_semantic_table) |table| {
                _ = model_source.setSemanticState(regions, instances, table);
            } else _ = model_source.setFaceSemantics(regions, instances);
        } else if (old_semantic_table) |table| {
            // A topology-growing caller installs its exact new rows immediately
            // after this shared replacement. Keep the dictionary alive across
            // retain() so those ids never become nameless in between or at commit.
            _ = model_source.setSemanticTableJson(table);
        }
    } else if (old_semantic_table) |table| {
        _ = model_source.setSemanticTableJson(table);
    };
    z3d.applyCarriedFaceColors(old_colors, count / 3);
    if (!z3d.stashHostMesh(key, new_verts[0..need], count)) return false;
    return true;
}

/// Swap to indexed-lowered geometry without rebuilding or recolouring the live paint
/// atlas. `new_verts` already carries the old atlas's interpolated UVs. The paint
/// program and raster remain recoverable while painting is locked; an explicit atlas
/// remake is the point that resets the now-stale strokes and derives a fresh layout.
pub fn replaceActiveEditMeshPreservingAtlas(
    new_verts: []const f32,
    count: u32,
    groups: ?[]const u32,
    colors: []const u8,
    logical: z3d.LogicalTopologyReplacement,
) bool {
    if (!z3d.residentMutationAllowed(.geometry_journal)) return false;
    const need = @as(usize, count) * 8;
    if (count < 3 or count % 3 != 0 or new_verts.len < need) return false;
    if (colors.len != @as(usize, count / 3) * 4 or model_paint.atlas() == null) return false;
    if (groups) |rows| if (rows.len < @as(usize, count / 3)) return false;
    if (!z3d.logicalReplacementPreflight(new_verts, count, logical)) return false;

    const old_ranges: ?[]u32 = if (model_source.partRanges()) |ranges|
        (std.heap.c_allocator.dupe(u32, ranges) catch null)
    else
        null;
    defer if (old_ranges) |ranges| std.heap.c_allocator.free(ranges);
    const old_materials: ?[]u32 = if (model_source.faceMaterials()) |rows|
        (std.heap.c_allocator.dupe(u32, rows) catch null)
    else
        null;
    defer if (old_materials) |rows| std.heap.c_allocator.free(rows);
    const old_semantic_table: ?[]u8 = if (model_source.semanticTableJson()) |json|
        (std.heap.c_allocator.dupe(u8, json) catch null)
    else
        null;
    defer if (old_semantic_table) |json| std.heap.c_allocator.free(json);
    const key = z3d.g_edit_key orelse return false;
    const edit_copy = std.heap.c_allocator.dupe(f32, new_verts[0..need]) catch return false;
    var edit_copy_adopted = false;
    defer if (!edit_copy_adopted) std.heap.c_allocator.free(edit_copy);

    // Restore any orange face tint into true paint while the OLD face indices and
    // layout still own its saved patches. The preserved atlas must never capture UI.
    mesh_edit.clearSelection();
    if (!model_paint.setTargetPreservingAtlas(z3d.g_edit_key_hash, new_verts, count, groups)) return false;
    z3d.g_paint_layout_stale = true;

    mesh_edit.reset();
    z3d.clearActiveEditGeometry();
    z3d.g_edit_verts = edit_copy;
    z3d.g_edit_count = count;
    z3d.bumpEditGeometryGeneration();
    edit_copy_adopted = true;
    if (!z3d.stashHostMesh(key, new_verts[0..need], count)) return false;

    if (!z3d.replaceSourceGeometryWithLogical(key, new_verts[0..need], count, logical)) return false;
    z3d.g_save_displayed_projection = false;
    if (groups) |rows| model_source.setFaceGroups(rows);
    if (old_ranges) |ranges| model_source.setPartRanges(ranges);
    if (old_materials) |rows| if (rows.len == count / 3) model_source.setFaceMaterials(rows);
    if (old_semantic_table) |table| _ = model_source.setSemanticTableJson(table);
    if (!z3d.applyExactSourceFaceColors(colors, count / 3)) return false;
    // setTargetPreservingAtlas can only retain opacity by the old displayed index.
    // Indexed subset/reorder installs provide the exact parented colour table, so
    // re-parent metadata without touching a single retained texture pixel.
    var face: u32 = 0;
    while (face < count / 3) : (face += 1) {
        if (!model_paint.setFaceAlphaMetadata(face, colors[@as(usize, face) * 4 + 3])) return false;
    }
    return true;
}

pub fn edgeSharesVertex(a: mesh_edit.Edge, b: mesh_edit.Edge) bool {
    return a[0] == b[0] or a[0] == b[1] or a[1] == b[0] or a[1] == b[1];
}

pub fn dist2(a: [3]f32, b: [3]f32) f32 {
    const d = z3d.vsub(a, b);
    return z3d.vdot(d, d);
}

pub fn appendCurrentDisplayed(list: *std.ArrayListUnmanaged(f32)) bool {
    const verts = z3d.g_edit_verts orelse return false;
    const need = @as(usize, z3d.g_edit_count) * 8;
    if (need > verts.len) return false;
    return z3d.appendFloats(list, verts[0..need]);
}

pub const FaceExtrudeEntity = struct {
    grouped: bool,
